// ======================= CONFIG — EDIT ME =======================
const CONFIG = {
  GHL_TOKEN: 'pit-REPLACE_WITH_PRIVATE_INTEGRATION_TOKEN', // GHL > Settings > Private Integrations
  LOCATION_ID: 'REPLACE_WITH_LOCATION_ID',
  // GHL custom field IDs (create them as Single Line TEXT fields)
  FIELD_IDS: {
    confirmationSent: 'REPLACE_webinar_confirmation_sent', // "yes" once confirmation is sent
    sequenceStep:     'REPLACE_webinar_sequence_step',     // number of follow-ups already sent
    nextSendAt:       'REPLACE_webinar_next_send_at',      // ISO date of next follow-up
    lastSentAt:       'REPLACE_webinar_last_sent_at',      // ISO date of last email sent
  },
  REGISTERED_TAG: 'webinar-registered',
};
const GHL = 'https://services.leadconnectorhq.com';
const ghlHeaders = {
  Authorization: `Bearer ${CONFIG.GHL_TOKEN}`,
  Version: '2021-07-28',
  Accept: 'application/json',
  'Content-Type': 'application/json',
};
// ================================================================

const WEBINAR = {
  title: 'Your Webinar Title',
  dateText: 'Thursday, 2 October 2026 · 4:00 PM (WAT)',
  joinLink: 'https://your-webinar-link.com',
  hostName: 'Nike',
};
const DEDUP_WINDOW_HOURS = 24;

const raw = $input.first().json;
const body = raw.body ?? raw;
const cd = body.customData || body.custom_data || {};
const pick = (...v) => (v.find(x => typeof x === 'string' && x.trim()) || '').trim();

let contactId = pick(body.contact_id, body.contactId, body.contact?.id, cd.contact_id);
let email = pick(body.email, body.contact?.email, cd.email).toLowerCase();
let firstName = pick(body.first_name, body.firstName, body.contact?.firstName, cd.first_name);
let lastName = pick(body.last_name, body.lastName, body.contact?.lastName, cd.last_name);
let customFields = [];
let lookupError = null;

// ---- Resolve contact from GHL (fills gaps + reads guard field) ----
try {
  if (contactId) {
    const res = await this.helpers.httpRequest({
      method: 'GET', url: `${GHL}/contacts/${contactId}`, headers: ghlHeaders, json: true,
    });
    const c = res.contact || {};
    email = email || (c.email || '').toLowerCase();
    firstName = firstName || c.firstName || '';
    lastName = lastName || c.lastName || '';
    customFields = c.customFields || [];
  } else if (email) {
    const res = await this.helpers.httpRequest({
      method: 'GET',
      url: `${GHL}/contacts/search/duplicate?locationId=${CONFIG.LOCATION_ID}&email=${encodeURIComponent(email)}`,
      headers: ghlHeaders, json: true,
    });
    const c = res.contact || {};
    contactId = c.id || '';
    firstName = firstName || c.firstName || '';
    lastName = lastName || c.lastName || '';
    customFields = c.customFields || [];
  }
} catch (e) {
  lookupError = e.message; // continue — static-data guard still protects us
}

const base = { contactId, email, firstName, lastName, fullName: `${firstName} ${lastName}`.trim(), lookupError };
const stop = (reason) => [{ json: { process: false, reason, ...base } }];

// ---- Validate ----
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) return stop('invalid_email');

// ---- Guard 1: GHL field ----
const sentFlag = customFields.find(f => f.id === CONFIG.FIELD_IDS.confirmationSent)?.value;
if (String(sentFlag || '').toLowerCase() === 'yes') return stop('already_sent');

// ---- Guard 2: n8n static data (catches rapid duplicate webhooks) ----
const sd = $getWorkflowStaticData('global');
sd.confirmations = sd.confirmations || {};
const now = Date.now();
for (const [k, ts] of Object.entries(sd.confirmations)) {
  if (now - new Date(ts).getTime() > 30 * 24 * 3600e3) delete sd.confirmations[k];
}
const key = contactId || email;
const last = sd.confirmations[key];
if (last && now - new Date(last).getTime() < DEDUP_WINDOW_HOURS * 3600e3) return stop('duplicate_recent');

// ---- Build email ----
const name = firstName || 'there';
const subject = `You're in! ${WEBINAR.title} — ${WEBINAR.dateText}`;
const html = `
<div style="font-family:Arial,sans-serif;max-width:560px;margin:auto;color:#222;line-height:1.6">
  <h2 style="margin-bottom:4px">You're registered, ${name}! 🎉</h2>
  <p>Thanks for signing up for <b>${WEBINAR.title}</b>.</p>
  <p><b>When:</b> ${WEBINAR.dateText}</p>
  <p style="margin:24px 0">
    <a href="${WEBINAR.joinLink}" style="background:#ff6d2d;color:#fff;padding:12px 22px;border-radius:6px;text-decoration:none;font-weight:bold">Join the webinar</a>
  </p>
  <p>Add it to your calendar so you don't miss it. I'll send you a few helpful emails before and after the session.</p>
  <p>See you there,<br>${WEBINAR.hostName}</p>
</div>`;

return [{ json: { process: true, reason: 'ok', ...base, dedupKey: key, subject, html, webinar: WEBINAR } }];

// ======================= CONFIG — EDIT ME =======================
const CONFIG = {
  GHL_TOKEN: 'pit-REPLACE_WITH_PRIVATE_INTEGRATION_TOKEN', // GHL > Settings > Private Integrations
  LOCATION_ID: 'REPLACE_WITH_LOCATION_ID',
  // GHL custom field IDs (create them as Single Line TEXT fields)
  FIELD_IDS: {
    confirmationSent: 'REPLACE_webinar_confirmation_sent', // "yes" once confirmation is sent
    sequenceStep:     'REPLACE_webinar_sequence_step',     // number of follow-ups already sent
    nextSendAt:       'REPLACE_webinar_next_send_at',      // ISO date of next follow-up
    lastSentAt:       'REPLACE_webinar_last_sent_at',      // ISO date of last email sent
  },
  REGISTERED_TAG: 'webinar-registered',
};
const GHL = 'https://services.leadconnectorhq.com';
const ghlHeaders = {
  Authorization: `Bearer ${CONFIG.GHL_TOKEN}`,
  Version: '2021-07-28',
  Accept: 'application/json',
  'Content-Type': 'application/json',
};
// ================================================================

// Must match the first follow-up delay you want in the sequence workflow
const FIRST_FOLLOWUP_DELAY_HOURS = 24;

const c = $('Validate + Resolve Contact + Guard').first().json;
const gmail = $input.first().json;
const now = new Date();
const nextSendAt = new Date(now.getTime() + FIRST_FOLLOWUP_DELAY_HOURS * 3600e3).toISOString();

let ghlUpdated = false;
let ghlError = null;

if (c.contactId) {
  try {
    await this.helpers.httpRequest({
      method: 'PUT',
      url: `${GHL}/contacts/${c.contactId}`,
      headers: ghlHeaders,
      body: {
        customFields: [
          { id: CONFIG.FIELD_IDS.confirmationSent, field_value: 'yes' },
          { id: CONFIG.FIELD_IDS.sequenceStep, field_value: '0' },
          { id: CONFIG.FIELD_IDS.nextSendAt, field_value: nextSendAt },
          { id: CONFIG.FIELD_IDS.lastSentAt, field_value: now.toISOString() },
        ],
      },
      json: true,
    });
    await this.helpers.httpRequest({
      method: 'POST',
      url: `${GHL}/contacts/${c.contactId}/tags`,
      headers: ghlHeaders,
      body: { tags: [CONFIG.REGISTERED_TAG] },
      json: true,
    });
    ghlUpdated = true;
  } catch (e) {
    ghlError = e.message;
  }
} else {
  ghlError = 'no_contact_id';
}

// Local guard so retries/duplicate webhooks don't re-send
const sd = $getWorkflowStaticData('global');
sd.confirmations = sd.confirmations || {};
sd.confirmations[c.dedupKey] = now.toISOString();

return [{
  json: {
    contactId: c.contactId,
    email: c.email,
    fullName: c.fullName || c.email,
    webinarTitle: c.webinar?.title,
    messageId: gmail.id || null,
    confirmedAt: now.toISOString(),
    nextSendAt,
    ghlUpdated,
    ghlError,
  },
}];
